<script setup lang="ts">import{ref}from'vue';const p=defineProps<{busy:boolean;error:string;initialServer:string}>();const emit=defineEmits<{pair:[code:string,serverUrl:string]}>();const code=ref(''),serverUrl=ref(p.initialServer);function submit(){const value=code.value.replace(/\D/g,'');if(value.length===6&&serverUrl.value.trim())emit('pair',value,serverUrl.value.trim())}function onInput(e:Event){const target=e.target as HTMLInputElement;code.value=target.value.replace(/\D/g,'').slice(0,6)}</script>
<template><main class="pairing"><section class="pair-card"><img class="pair-logo" src="/icon.svg" alt="Codex Remote"><p class="eyebrow">CODEX REMOTE</p><h1>连接你的 Codex</h1><p>填写运行服务的电脑地址和终端中显示的六位一次性配对码。</p><label>服务器地址<input v-model="serverUrl" class="server-url-input" type="url" inputmode="url" autocomplete="url" placeholder="http://192.168.1.10:8787" @keyup.enter="submit"></label><label>配对码<input :value="code" maxlength="6" inputmode="numeric" autocomplete="one-time-code" placeholder="000000" @input="onInput" @keyup.enter="submit"></label><button class="primary wide" :disabled="busy||code.length!==6||!serverUrl.trim()" @click="submit">{{busy?'正在连接…':'连接此设备'}}</button><p v-if="error" class="form-error">{{error}}</p><div class="pair-security"><span>◇</span><div><strong>私密且自托管</strong><small>访问凭据仅存储于本设备，不会显示在页面中，也不会发送到第三方。</small></div></div></section></main></template>
